drop function public.search_community(text);
create function public.search_community(search_text text,page_cursor jsonb default '{}')returns jsonb language sql stable security invoker set search_path=''as $$with
matching_posts as(select *from public.posts where length(search_text)between 2 and 200 and(id>coalesce((page_cursor->>'posts')::uuid,'00000000-0000-0000-0000-000000000000'::uuid))and to_tsvector('english',title||' '||body||' '||array_to_string(tags,' '))@@websearch_to_tsquery('english',search_text)order by id limit 30),
matching_profiles as(select *from public.profiles where length(search_text)between 2 and 200 and(id>coalesce((page_cursor->>'profiles')::uuid,'00000000-0000-0000-0000-000000000000'::uuid))and to_tsvector('english',name||' '||methods||' '||equipment||' '||array_to_string(interests,' '))@@websearch_to_tsquery('english',search_text)order by id limit 30),
matching_projects as(select *from public.projects where length(search_text)between 2 and 200 and(id>coalesce((page_cursor->>'projects')::uuid,'00000000-0000-0000-0000-000000000000'::uuid))and to_tsvector('english',title||' '||problem||' '||methods||' '||needs||' '||equipment)@@websearch_to_tsquery('english',search_text)order by id limit 30)
select jsonb_build_object('posts',(select coalesce(jsonb_agg(x order by id),'[]')from matching_posts x),'profiles',(select coalesce(jsonb_agg(x order by id),'[]')from matching_profiles x),'projects',(select coalesce(jsonb_agg(x order by id),'[]')from matching_projects x),'cursor',jsonb_build_object('posts',(select case when count(*)=30 then max(id::text)else null end from matching_posts),'profiles',(select case when count(*)=30 then max(id::text)else null end from matching_profiles),'projects',(select case when count(*)=30 then max(id::text)else null end from matching_projects)))$$;
revoke all on function public.search_community(text,jsonb)from public;grant execute on function public.search_community(text,jsonb)to anon,authenticated;
-- Topic arrays remain checked separately in FTS query because array_to_string is not immutable.
create function public.community_health()returns jsonb language plpgsql stable security definer set search_path=''as $$begin if not private.has_role('admin')then raise insufficient_privilege;end if;return jsonb_build_object('active_eligible_members',(select count(*)from public.profiles where membership='approved'and not suspended),'pending_applications',(select count(*)from public.membership_applications where status in('pending','appeal','needs_evidence')),'open_reports',(select count(*)from public.reports where status='open'),'published_questions',(select count(*)from public.posts where kind='question'and state='published'and visibility<>'private'),'resolved_questions',(select count(*)from public.posts where kind='question'and state='published'and visibility<>'private'and(accepted_answer_id is not null or resolution<>'')));end$$;
revoke all on function public.community_health()from public,anon;grant execute on function public.community_health()to authenticated;
